function _getStepDataFromObject(stepObject) {
        var tooltipContent, element, tooltipPosition;

        if (typeof stepObject.template === 'function') {
            tooltipContent = stepObject.template({ step: stepObject.step });
        } else {
            tooltipContent = _getElementHTML(this._rootElement.querySelector(stepObject.template));
        }

        if (stepObject.element) {
            element = this._rootElement.querySelector(stepObject.element);
            tooltipPosition = stepObject.tooltipPosition || this._options.tooltipPosition;
        } else {
            element = this._rootElement;
            tooltipPosition = 'center';
        }

        return {
            // the element to highlight
            element: element,
            // content of the intro tooltip
            content: tooltipContent,
            step: stepObject.step,
            // custom scrolling offset for this step
            scrollTo: stepObject.scrollTo === undefined ? null : stepObject.scrollTo,
            tooltipPosition: tooltipPosition
        };
    }

pub fn entity_from_handle(handle: NativeEntity) -> Result<Box<dyn Entity>, EntityFromHandleError> {
  unsafe {
    if natives::entity::does_entity_exist(handle) {
      let entity_type = natives::entity::get_entity_type(handle);
      match entity_type {
        1 => {
          Ok(Box::new(
            Ped::try_from(handle).expect("Ped::try_from failed")
          ))
        } // Ped
        2 => {
          Ok(Box::new(
            Vehicle::try_from(handle).expect("Vehicle::try_from failed")
          ))
        } // Vehicle
        3 => {
          Ok(Box::new(
            Object::try_from(handle).expect("Object::try_from failed")
          ))
        } // Object
        _ => {
          Err(EntityFromHandleError::UnrecognizedEntity(
            UnrecognizedEntityTypeError {
              handle,
              entity_type
            }
          ))
        }
      }
    } else {
      Err(EntityFromHandleError::NotAnEntityHandle(
        NotAnEntityHandleError { handle }
      ))
    }
  }
}

int32_t TransposeChannelDim(const std::vector<uint32_t>& perm,
                                   int32_t channel_dim) {
  if (channel_dim < 0) {
    TFLITE_LOG_PROD(TFLITE_LOG_ERROR, "invalid channel_dim");
    return -1;
  }
  for (uint32_t i = 0; i < perm.size(); i++) {
    if (channel_dim == perm.at(i)) {
      return i;
    }
  }
  TFLITE_LOG_PROD(TFLITE_LOG_ERROR, "Can't find channle_dim");
  return -1;
}

